'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isInfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var floorf = require( '@stdlib/math/base/special/floorf' );
var powf = require( '@stdlib/math/base/special/powf' );
var absf = require( '@stdlib/math/base/special/absf' );
var log10 = require( '@stdlib/math/base/special/log10' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );


// MAIN //

/**
* Rounds a single-precision floating-point number to the nearest power of `10` on a linear scale.
*
* @param {number} x - input value
* @returns {number} rounded value
*
* @example
* var v = round10f( 3.1415926 );
* // returns 1.0
*
* @example
* var v = round10f( 123.45 );
* // returns 100.0
*
* @example
* var v = round10f( -2.5 );
* // returns -1.0
*
* @example
* var v = round10f( -0.0 );
* // returns -0.0
*/
function round10f( x ) {
	var ax;
	var e0;
	var e1;
	var y0;
	var y1;

	x = f32( x );
	if ( isnanf( x ) || isInfinitef( x ) || x === 0.0 ) {
		return x;
	}
	ax = absf( x );

	// Solve the equation `10^e = ax` for `e` and find the exponent of the previous integer power of ten:
	e0 = floorf( f32( log10( ax ) ) );

	// Find the exponent of the next integer power of ten:
	e1 = f32( e0 + 1 );

	// Compute the previous and next integer powers of ten:
	y0 = powf( 10.0, e0 );
	y1 = powf( 10.0, e1 );

	// Find the closest power of ten, rounding ties to the next integer power of ten (note: as single-precision values are exactly representable in double-precision and the operands are of similar magnitude, both differences are computed exactly in double-precision arithmetic):
	if ( ax - y0 < y1 - ax ) {
		return ( x < 0.0 ) ? f32( -y0 ) : y0;
	}
	return ( x < 0.0 ) ? f32( -y1 ) : y1;
}


// EXPORTS //

module.exports = round10f;
